//! the menu icons: pixel art, as indices into one shared palette.
//!
//! Generated. Edit the PNGs beside this file and re-run:
//!
//! ```text
//! tools/artgen/pixels2rs.py crates/catcard-ui/src/art/menu-icons \
//!     crates/catcard-ui/src/art/menuicons.rs --background 303030
//! ```
//!
//! One palette for the whole set, because the panel maps a scanline's indices
//! through a single 16-entry table at send time and these are shown side by
//! side. Index 0 is the transparent background and is not drawn; index 15 is
//! white, which is what the labels draw in too.

use super::indexed::Indexed;

/// The colours all 40 icons are drawn from, RGB565.
///
/// Index 0 is the background (#303030): the art leaves it alone and the
/// screen behind is cleared to it, so it is what shows through.
#[rustfmt::skip]
pub const PALETTE: [u16; 16] = [
    0x3186, 0x0000, 0x344F, 0x6616, 0x63B1, 0xBE3B, 0xC2E3, 0xF465, 0xF619, 0xFEAB, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0xFFFF,
];

